 if(!testMode){testReturnSlot=activeSlot;save=JSON.parse(JSON.stringify(save));testMode=true;activeSlot={id:'test',name:'Atelier de test',save};}
 save.gold=Infinity;save.spells={owned:GG.spells.map(p=>p.id),slots:[GG.spells[0]?.id||0,0,0,0]};save.passives={hawkEye:1,instruments:1};save.witchFound=true;if(save.collection){delete save.collection.launch;delete save.collection.wing;}save.owned.wing=40;save.owned.launch=24;save.levels.launch=Math.max(0,Math.min(24,level));save.wallDamage={};
 forgeSelections.launch=save.levels.launch;inspectionPaused=false;
 $('profile-label').textContent='ATELIER DE TEST';$('title-screen').hidden=true;$('profile-screen').hidden=true;$('play-shell').hidden=false;
