$('test-launch-select').innerHTML=GGLaunch.items.map((g,i)=>`<option value="${i}">${i+1} · ${g.name}</option>`).join('');
$('test-launch-select').onchange=e=>startTest(Number(e.target.value));
$('test-retry').onclick=()=>startTest(save.levels.launch);
$('test-forge').onclick=()=>{ready();showTab('forge');};
$('test-exit').onclick=()=>{GGCourse.setTestRamp();testRampHeight=0;testRampLength=0;const slot=testReturnSlot;testMode=false;$('test-controls').hidden=true;activeSlot=slot;save=slot?.save??GG.fresh();if(slot)enter(slot);else toTitle();};
$('title-test').onclick=()=>startTest(0);

$('title-test').disabled=!GGRiders.loaded;
GGRiders.ready.then(()=>{$('title-test').disabled=false;if(state==='ready')$('launch-button').disabled=false;renderForge();}).catch(e=>{$('title-status').textContent=e.message+' — rechargez le jeu.';$('saving').textContent=e.message;});

let testRampHeight=0,testRampLength=0;
function refreshTestRamp(){const label=document.getElementById('test-ramp-values');if(label)label.textContent='Hauteur '+(testRampHeight>=0?'+':'')+testRampHeight+' · Fin '+(testRampLength>=0?'+':'')+testRampLength;}
document.querySelectorAll('[data-ramp-adjust]').forEach(button=>button.addEventListener('click',()=>{if(!testMode)return;const axis=button.dataset.rampAdjust,delta=Number(button.dataset.delta);const values=GGCourse.setTestRamp(testRampHeight+(axis==='height'?delta:0),testRampLength+(axis==='length'?delta:0));testRampHeight=values.height;testRampLength=values.length;refreshTestRamp();startTest(save.levels.launch);}));
document.getElementById('test-ramp-reset').onclick=()=>{if(!testMode)return;GGCourse.setTestRamp();testRampHeight=0;testRampLength=0;refreshTestRamp();startTest(save.levels.launch);};

GGDelta.ready.then(()=>renderForge());

// Spell bar: four parchment slots, keys 1–4, cooldown wipe and essence check. Tapping a slot casts too.
let spellBarKey='';
function castSlot(i){const id=flight?.spellSlots?.[i];if(!id||state!=='flight'||paused)return;if(!GG.castSpell(flight,id))tone(140,.12,'triangle');}
function updateSpellBar(){
 const bar=$('spell-bar');const show=flight&&['launching','flight'].includes(state)&&(flight.spellsOwned?.length>0);bar.hidden=!show;if(!show)return;bar.style.bottom=testMode?'214px':'';
 const slots=flight.spellSlots||[0,0,0,0],key=slots.join(',');
 if(spellBarKey!==key){spellBarKey=key;bar.innerHTML=slots.map((id,i)=>{const sp=GG.spells.find(p=>p.id===id);return `<button class="spell-slot ${sp?'':'empty'}" data-cast="${i}" ${sp?'':'disabled'} aria-label="${sp?sp.name+' · touche '+(i+1):'Emplacement libre '+(i+1)}"><span class="key">${i+1}</span>${sp?spellIcon(sp.id)+'<small>'+sp.short+'</small>':'<small>—</small>'}<i class="cooldown"></i></button>`;}).join('');}
 slots.forEach((id,i)=>{const sp=GG.spells.find(p=>p.id===id);if(!sp)return;const el=bar.children[i],cd=(flight.spellCooldown?.[id]||0)/sp.cooldown,noFuel=flight.fuel<sp.cost*flight.maxFuel;el.classList.toggle('active',id===1&&flight.slowLeft>0);el.classList.toggle('no-fuel',noFuel&&cd<=0);el.style.setProperty('--cd',cd.toFixed(3));});
}
$('spell-bar').onclick=e=>{const b=e.target.closest('[data-cast]');if(b)castSlot(Number(b.dataset.cast));};
function updateInstruments(){
 document.body.classList.toggle('no-boost',!!flight&&!(flight.maxFuel>0));document.body.classList.toggle('fart-mode',!!flight?.fartMode);{const label=flight?.fartMode?'GAZ 💨':'ESSENCE',touch=state==='launching'&&rampJump&&!rampJump.pressed?'SAUTE !':flight?.fartMode?'PROUT !':'FEU !',button=document.querySelector('.touch-controls [data-hold="boost"]');if($('fuel-label').textContent!==label)$('fuel-label').textContent=label;if(button&&button.textContent!==touch)button.textContent=touch;}
 const panel=$('flight-instruments'),inFlight=!!flight&&['launching','flight','landing'].includes(state),ownsDials=GG.passiveLevel(save,'instruments')>0;$('instruments-toggle').hidden=!(inFlight&&ownsDials);$('instruments-toggle').setAttribute('aria-pressed',String(save.instrumentsShown!==false));panel.hidden=!inFlight||!ownsDials||save.instrumentsShown===false;document.body.classList.toggle('instruments-on',!panel.hidden);if(panel.hidden)return;
 const v=state==='launching'?GGCourse.launchPose(Math.max(0,launchTime/launchDuration),flight.launchAngle,flight.launchSpeed,flight.l.launch).speed:Math.hypot(flight.vx,flight.vy);
 const max=GG.parameters(flight.l).maxSpeed*3.6,speed=v*3.6;
 $('dial-needle').style.transform=`rotate(${-130+260*Math.min(1,speed/max)}deg)`;
 $('dial-speed').textContent=Math.round(speed);$('dial-max').textContent=Math.round(max);
 const altitude=state==='launching'?(485-GGCourse.launchPose(Math.max(0,launchTime/launchDuration),flight.launchAngle,flight.launchSpeed,flight.l.launch).y)/GGCourse.SCALE:flight.y;
 $('dial-altitude').textContent=Math.round(Math.max(0,altitude)).toLocaleString('fr');
 $('altitude-fill').style.height=Math.min(100,Math.max(0,altitude)/Math.max(1000,flight.maxY)*100)+'%';
 panel.style.bottom=testMode?'116px':'';
}

document.addEventListener('click',event=>{
 const button=event.target.closest?.('button');
 if(!button||button.disabled||!sound)return;
 if(!enableAudio())return;
 soundEngine?.sample('click',.36);
},true);

// ---- "You can now buy X!" celebration when a purchase unlocks a new family of launch or wing gear.
function unlockedFamilies(){const out=[];for(const id of ['launch','wing'])for(const g of GG.gearFamilies(id))if(GG.familyUnlocked(save,id,g.start))out.push(id+':'+g.start);return out;}
function announceUnlocks(before){
 const fresh=unlockedFamilies().filter(k=>!before.includes(k));if(!fresh.length)return;
 const names=fresh.map(k=>{const [id,start]=k.split(':'),g=GG.gearFamilies(id).find(g=>g.start===Number(start));return g?.name?{tab:id==='launch'?'LA GLISSE':'DANS LES AIRS',name:g.name}:null;}).filter(Boolean);if(!names.length)return;
 const banner=$('unlock-banner');
 banner.innerHTML=`<div class="confetti">${Array.from({length:46},(_,i)=>`<i style="left:${(i*37)%100}%;background:${['#ff6b6b','#ffd93d','#6bcb77','#4d96ff','#ff8fd8'][i%5]};animation-delay:${(i%9)*-.33}s;animation-duration:${2.4+(i%5)*.35}s"></i>`).join('')}</div><div class="card"><span class="kicker">🎉 NOUVEAUTÉ À LA FORGE ! 🎉</span><h2 style="font-size:${names.length>1?'clamp(24px,4vw,44px)':''}">${names.map(n=>n.name).join(' & ')}</h2><p>Tu peux maintenant acheter ${names.length>1?'ces objets':'cet objet'} dans l’onglet <b>${[...new Set(names.map(n=>n.tab))].join(' et ')}</b> !</p><small>Clique pour continuer</small></div>`;
 banner.hidden=false;soundEngine?.coin(true);[660,880,1100].forEach((f,i)=>setTimeout(()=>tone(f,.14,'triangle'),i*120));
 clearTimeout(announceUnlocks.timer);const hide=()=>{banner.hidden=true;banner.innerHTML='';};announceUnlocks.timer=setTimeout(hide,6000);banner.onclick=hide;
}

// ---- The witch is freed: pause the flight and let her introduce her magic shop.
function showWitchIntro(){if(!flight||!['flight','launching','landing'].includes(state))return;paused=true;soundEngine?.pauseEffects();keys={};$('pause').textContent='▶';const el=$('witch-intro');el.hidden=false;{const gift=$('witch-gift'),g=gift.getContext('2d');g.clearRect(0,0,gift.width,gift.height);g.save();g.translate(gift.width/2,gift.height/2);GGEquipment.draw(g,'boost',0,0,0,1);g.restore();}const close=()=>{el.hidden=true;paused=false;$('pause-panel').hidden=true;$('pause').textContent='Ⅱ';canvas.focus();refresh();};el.querySelector('button').onclick=close;el.onclick=e=>{if(e.target===el)close();};}
$('instruments-toggle').onclick=()=>{save.instrumentsShown=save.instrumentsShown===false;persist();};
$('ending-continue').onclick=()=>{endingDone=true;$('ending').hidden=true;};
